class Solution {
public:
    long long maxAlternatingSum(vector<int>& nums) {
        const long long NEG = -1000000000000000LL; // safely below any real value (max |sum| ≈ 10^10)
        long long add = NEG; // best alternating sum of an even-length subsequence (next pick is added)
        long long sub = NEG; // best alternating sum of an odd-length subsequence (next pick is subtracted)
        // Empty subsequence has even length 0 and sum 0, so seed add with 0.
        add = 0;
        for (int x : nums) {
            long long nxtAdd = max(add, sub - x); // skip, or take x at an odd index (subtract)
            long long nxtSub = max(sub, add + x); // skip, or take x at an even index (add)
            add = nxtAdd;
            sub = nxtSub;
        }
        return max(add, sub);
    }
};
